//! A stand-in for every native the target client binds that is not ported yet: its id and the
//! retail function it stands for. Calling one stops the run cleanly, naming both.
//!
//! The natives a host binds from its own model (the client runtime binds these over the shared
//! natives) are listed apart ([`host_bound`]): a host without a model stops at them the same way.
//!
//! Generated by the private stub generator from the client's binding table; regenerate it
//! after porting a native (the generator leaves ported ones out).

use auberean_script::value::NativeId;
use auberean_script::{Binding, NativeTable};

/// A native not ported yet: the retail function it stands for.
macro_rules! not_ported {
    ($id:literal) => {
        Binding::NotPorted($id)
    };
}

/// A native a host binds from its own model: the retail function it stands for here.
macro_rules! host_bound {
    ($id:literal) => {
        Binding::NotPorted($id)
    };
}

/// Bind every stand-in.
pub fn bind_all(t: &mut NativeTable) {
    for (id, b) in STUBS.iter().chain(HOST) {
        t.bind(NativeId(*id), *b);
    }
}

/// The natives a host binds from its own model, by id.
pub fn host_bound() -> impl Iterator<Item = NativeId> {
    HOST.iter().map(|(id, _)| NativeId(*id))
}

